import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000003L;

    // Fast doubling Fibonacci: returns (F(n), F(n+1))
    static long[] fib(long n) {
        if (n == 0) return new long[]{0, 1};
        long[] p = fib(n >> 1);
        long a = p[0]; // F(k)
        long b = p[1]; // F(k+1)

        long c = (a * ((2 * b % MOD - a + MOD) % MOD)) % MOD;          // F(2k)
        long d = ((a * a) % MOD + (b * b) % MOD) % MOD;               // F(2k+1)

        if ((n & 1) == 0) return new long[]{c, d};
        else return new long[]{d, (c + d) % MOD};
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null || s.trim().isEmpty()) {
            System.out.println(0);
            return;
        }
        long n = Long.parseLong(s.trim());

        // Answer = F_{2n+1} mod MOD
        long idx = 2 * n + 1;
        long ans = fib(idx)[0] % MOD;
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000003L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        int n = Integer.parseInt(s.trim());

        if (n == 0) {
            System.out.println(0);
            return;
        }

        int size = 2 * n;
        boolean[][] used = new boolean[size][size];
        long empty = 0;

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (!used[i][j]) {
                    int maxK = 0;
                    int limit = size - Math.max(i, j);
                    for (int k = 2; k <= limit; k++) {
                        boolean ok = true;
                        for (int r = 0; r < k && ok; r++) {
                            for (int c = 0; c < k && ok; c++) {
                                if (r + c >= k) continue;
                                int rr = i + r;
                                int cc = j + c;
                                if (rr >= size || cc >= size || used[rr][cc]) {
                                    ok = false;
                                }
                            }
                        }
                        if (ok) maxK = k;
                        else break;
                    }
                    if (maxK >= 2) {
                        for (int r = 0; r < maxK; r++) {
                            for (int c = 0; c < maxK; c++) {
                                if (r + c < maxK) {
                                    used[i + r][j + c] = true;
                                }
                            }
                        }
                    } else {
                        empty++;
                    }
                }
            }
        }

        System.out.println(empty % MOD);
    }
}

