import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000003L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        int n = Integer.parseInt(s.trim());
        int size = 2 * n;
        boolean[][] used = new boolean[size][size];
        long empty = 0;

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (!used[i][j]) {
                    int maxK = maxCookieSize(i, j, used, size);
                    if (maxK >= 2) {
                        placeCookie(i, j, maxK, used);
                    } else {
                        empty++;
                    }
                }
            }
        }

        System.out.println(empty % MOD);
    }

    // Determine the largest k >= 2 such that a k-cookie can be placed
    private static int maxCookieSize(int r, int c, boolean[][] used, int size) {
        int maxPossible = size - r; // cookie height limited by bottom
        if (maxPossible < 2) return -1;

        int best = -1;
        for (int k = 2; k <= maxPossible; k++) {
            if (c + k - 1 >= size) break; // cookie width limited by right side
            if (canPlaceCookie(r, c, k, used)) {
                best = k;
            } else {
                break; // larger k won't fit if this one doesn't
            }
        }
        return best;
    }

    // Check if a k-cookie can be placed with top-left at (r,c)
    private static boolean canPlaceCookie(int r, int c, int k, boolean[][] used) {
        int size = used.length;
        if (r + k > size || c + k > size) return false;
        for (int i = 0; i < k; i++) {
            for (int j = 0; j <= i; j++) {
                if (used[r + i][c + j]) return false;
            }
        }
        return true;
    }

    // Mark cells of a k-cookie as used
    private static void placeCookie(int r, int c, int k, boolean[][] used) {
        for (int i = 0; i < k; i++) {
            for (int j = 0; j <= i; j++) {
                used[r + i][c + j] = true;
            }
        }
    }
}

