import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000003L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        int n = Integer.parseInt(s.trim());

        int size = 2 * n;
        boolean[][] occ = new boolean[size][size];

        // Precompute cookie shapes for k = 2..2n
        List<int[][]> cookies = new ArrayList<>();
        for (int k = 2; k <= size; k++) {
            List<int[]> cells = new ArrayList<>();
            for (int i = 0; i < k; i++) {
                for (int j = i; j < k; j++) {
                    cells.add(new int[]{i, j});
                }
            }
            int[][] arr = new int[cells.size()][2];
            for (int i = 0; i < cells.size(); i++) {
                arr[i][0] = cells.get(i)[0];
                arr[i][1] = cells.get(i)[1];
            }
            cookies.add(arr);
        }

        // Place cookies from largest to smallest
        for (int idx = cookies.size() - 1; idx >= 0; idx--) {
            int[][] cookie = cookies.get(idx);
            int k = idx + 2;
            for (int x = 0; x <= size - k; x++) {
                for (int y = 0; y <= size - k; y++) {
                    boolean can = true;
                    for (int[] c : cookie) {
                        int cx = x + c[0];
                        int cy = y + c[1];
                        if (occ[cx][cy]) {
                            can = false;
                            break;
                        }
                    }
                    if (can) {
                        for (int[] c : cookie) {
                            int cx = x + c[0];
                            int cy = y + c[1];
                            occ[cx][cy] = true;
                        }
                    }
                }
            }
        }

        long empty = 0;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (!occ[i][j]) empty++;
            }
        }

        System.out.println(empty % MOD);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000003L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        int n = Integer.parseInt(s.trim());

        long ans = 0;
        for (int k = 2; k <= 2 * n; k++) {
            long area = ((long) k * (k + 1) / 2) % MOD;
            long count = (long) (2 * n - k + 1);
            count = (count * count) % MOD;
            ans = (ans + area * count) % MOD;
        }

        long total = (long) (2 * n) * (2 * n) % MOD;
        long empty = (total - ans) % MOD;
        if (empty < 0) empty += MOD;

        System.out.println(empty);
    }
}

