        int n = Integer.parseInt(s.trim());

        long ans = 0;
        if (n >= 1) {
            long term1 = (long)n * (n - 1) / 2;
            long term2 = (long)n * (n - 1) * (2L * n - 1) / 6;
            ans = (term1 + term2) % MOD;
        }

        System.out.println(ans);
    }
